public class CommandLine_hasOption_TriageGen1Test {

    private CommandLine commandLine;
    private Map<String, String> options;

    @Before
    public void setUp() {
        options = new HashMap<>();
        commandLine = new CommandLine();
    }

    @Test
    public void testHasOption_Existing() {
        Option option = new Option("test", false, "Test option");
        commandLine.addOption(option);
        assertFalse("Option should not be found before adding to options map", commandLine.hasOption("test"));

        options.put("test", "value");
        commandLine.setOptions(Arrays.asList(option));
        commandLine.setOptionProperties(options);

        assertTrue("Option should be found", commandLine.hasOption("test"));
    }

    @Test
    public void testHasOption_NonExisting() {
        assertFalse("Non-existing option should not be found", commandLine.hasOption("nonExisting"));
    }

    @Test
    public void testHasOption_EmptyString() {
        assertFalse("Empty string option should not be found", commandLine.hasOption(""));
    }

    @Test
    public void testHasOption_Null() {
        assertFalse("Null option should not be found", commandLine.hasOption(null));
    }

    @Test
    public void testHasOption_AddOptionAfterCheck() {
        assertFalse("Initially, option should not be found", commandLine.hasOption("newOption"));

        Option option = new Option("newOption", false, "New option");
        commandLine.addOption(option);
        options.put("newOption", "value");
        commandLine.setOptions(Arrays.asList(option));
        commandLine.setOptionProperties(options);

        assertTrue("Option should be found after adding", commandLine.hasOption("newOption"));
    }
}
